import{_ as t,o,c as a,a7 as r}from"./chunks/framework.CWfAgRyf.js";const u=JSON.parse('{"title":"Implementing new Minecraft version support in Axolotl-PM","description":"How to implement new Minecraft version support in Axolotl-PM.","frontmatter":{"title":"Implementing new Minecraft version support in Axolotl-PM","outline":"deep","description":"How to implement new Minecraft version support in Axolotl-PM.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/developers/internals-docs/updating-minecraft-protocol"}]]},"headers":[],"relativePath":"docs/developers/internals-docs/updating-minecraft-protocol.md","filePath":"docs/developers/internals-docs/updating-minecraft-protocol.md","lastUpdated":null}'),i={name:"docs/developers/internals-docs/updating-minecraft-protocol.md"};function n(s,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="implementing-new-minecraft-version-support-in-axolotl-pm" tabindex="-1">Implementing new Minecraft version support in Axolotl-PM <a class="header-anchor" href="#implementing-new-minecraft-version-support-in-axolotl-pm" aria-label="Permalink to &quot;Implementing new Minecraft version support in Axolotl-PM&quot;">​</a></h1><p>Minecraft often makes changes to its network protocol, including adding new packets, removing old ones, or changing the structure of existing packets. Because of this, Axolotl-PM often needs to be updated to support the latest version of Minecraft.</p><p>This page will cover the basic process of analyzing and implementing protocol updates.</p><h2 id="pre-requisites" tabindex="-1">Pre-requisites <a class="header-anchor" href="#pre-requisites" aria-label="Permalink to &quot;Pre-requisites&quot;">​</a></h2><ul><li>Linux (WSL2 will work)</li><li>Linux version of <a href="https://www.minecraft.net/en-us/download/server/bedrock" target="_blank" rel="noreferrer">Bedrock Dedicated Server</a> compatible with your target version of Minecraft</li><li>Minecraft world with the desired features to test (optionally with experiments enabled, e.g. 1.21 Update)</li><li>Git clones of <a href="https://github.com/axolotl-pm/PocketMine-MP" target="_blank" rel="noreferrer">Axolotl-PM</a>, <a href="https://github.com/axolotl-pm/BedrockProtocol" target="_blank" rel="noreferrer">BedrockProtocol</a>, <a href="https://github.com/axolotl-pm/BedrockData" target="_blank" rel="noreferrer">BedrockData</a>, <a href="https://github.com/axolotl-pm/BedrockBlockUpgradeSchema" target="_blank" rel="noreferrer">BedrockBlockUpgradeSchema</a>, and <a href="https://github.com/axolotl-pm/BedrockItemUpgradeSchema" target="_blank" rel="noreferrer">BedrockItemUpgradeSchema</a></li><li>A local copy of <a href="https://github.com/pmmp/BedrockProtocolDumper" target="_blank" rel="noreferrer">BedrockProtocolDumper</a></li></ul><h2 id="step-1-generating-supporting-data-part-1" tabindex="-1">Step 1: Generating supporting data (part 1) <a class="header-anchor" href="#step-1-generating-supporting-data-part-1" aria-label="Permalink to &quot;Step 1: Generating supporting data (part 1)&quot;">​</a></h2><p>Axolotl-PM requires additional data from the new version of Minecraft to function correctly. This includes:</p><p>These data originate from several sources:</p><ol><li><a href="https://github.com/pmmp/bds-modding-devkit/blob/master/protocol_info_dumper.py" target="_blank" rel="noreferrer">protocol_info_dumper.py</a> which generates basic version info and packet ID lists for updating BedrockProtocol.</li><li>Mods of the Bedrock Dedicated Server that dump the needed data. This method is a pain, but it’s the only way to get some data.</li><li>Packet traces of the Bedrock Dedicated Server communicating with a vanilla Minecraft client.</li></ol><p>Tools to collect all of this data are provided in <a href="https://github.com/pmmp/bds-modding-devkit" target="_blank" rel="noreferrer">bds-modding-devkit</a>.</p><p>Follow the instructions in the <a href="https://github.com/pmmp/bds-modding-devkit" target="_blank" rel="noreferrer">modding toolkit</a> repository README to set up the modding environment and install the BDS version you want to dump data from.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Unfortunately, Mojang no longer publicly provide BDS builds with debugging symbols as of 1.21.40. <strong>This means that you need access to BDS builds provided by a server or Marketplace partner to generate the needed data.</strong></p><p>Some of the data can be scraped from the public protocol docs instead, but not all data can be collected from the docs either. This leaves third party servers dependent on the goodwill of Minecraft partners.</p></div><h3 id="generating-basic-protocol-info-from-bds" tabindex="-1">Generating basic protocol info from BDS <a class="header-anchor" href="#generating-basic-protocol-info-from-bds" aria-label="Permalink to &quot;Generating basic protocol info from BDS&quot;">​</a></h3><p>Use the <a href="https://github.com/pmmp/bds-modding-devkit/blob/master/protocol_info_dumper.py" target="_blank" rel="noreferrer">protocol info dumper</a> to generate <code>protocol_info.json</code> for <code>BedrockData</code>.</p><p>This script requires Python 3, <code>objdump</code> (install the <code>binutils</code> package), and a BDS binary with debugging symbols.</p><p>Use it like so: <code>python3 protocol_info_dumper.py ./bedrock_server_symbols.debug ./protocol_info.json</code></p><p>Once you have the file, put it in your <code>BedrockData</code> folder.</p><h3 id="getting-data-from-bds-via-mods" tabindex="-1">Getting data from BDS via mods <a class="header-anchor" href="#getting-data-from-bds-via-mods" aria-label="Permalink to &quot;Getting data from BDS via mods&quot;">​</a></h3><p>The mod code of interest can be found in the <a href="https://github.com/pmmp/bds-mod-mapping" target="_blank" rel="noreferrer">data extraction mod</a> main repository. This mod is preinstalled by the modding toolkit when you clone following the instructions in the README.</p><p>Once you’ve generated the data, copy all the files (not the folders) in <code>mapping_files/</code> to <code>BedrockData</code>.</p><p>There may be additional files that are not needed by <code>BedrockData</code>. You can ignore these.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>The code often needs to be updated to work with the latest version of the BDS. This guide won’t cover how to make the mods run on newest BDS, as the changes needed are usually different from version to version, and this guide would end up very long. You really should have general experience modding BDS before trying to get into this. If you need help, ask in the PMMP Discord server.</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Make sure the <code>input_files/old_block_palettes</code> submodule is up to date, and that it contains a block palette for the previous version of Minecraft. You’ll need this later for generating blockstate upgrade schemas.</p></div><h3 id="collecting-vanilla-vanilla-packet-traces" tabindex="-1">Collecting vanilla &lt;-&gt; vanilla packet traces <a class="header-anchor" href="#collecting-vanilla-vanilla-packet-traces" aria-label="Permalink to &quot;Collecting vanilla &lt;-&gt; vanilla packet traces&quot;">​</a></h3><p>The <a href="https://github.com/pmmp/bds-modding-devkit" target="_blank" rel="noreferrer">modding toolkit</a> also provides a <a href="https://github.com/pmmp/bds-modding-devkit/blob/master/tracer.py" target="_blank" rel="noreferrer">tracer script</a> that can be used to hook into a running instance of BDS and capture packet traces between a vanilla client and server. This script uses the <a href="https://frida.re" target="_blank" rel="noreferrer">Frida.re</a> Python API to hook into packet read and write functions in the BDS. The script has no impact on vanilla behaviour, guaranteeing the best quality data.</p><p>These traces can be used to generate data, and also to verify that your changes to <a href="https://github.com/axolotl-pm/BedrockProtocol" target="_blank" rel="noreferrer">BedrockProtocol</a> are correct.</p><p>Steps to capture packet traces:</p><ol><li>Create a new world in Minecraft on the target version. Make sure to enable any experiments which add new blocks or items, as these need to be present for generating data upgrade schemas.</li><li>Configure <code>server.properties</code> on your BDS to use the world you generated.</li><li>Start <code>bedrock_server_symbols.debug</code> directly (do not use <code>start.sh</code>).</li><li>In a separate terminal, run the following command: <code>sudo python3 tracer.py rw bedrock_server_symbols.debug</code>. This will hook into the running BDS instance and start capturing packet traces.</li><li>Join the BDS server using Minecraft. Do whatever in-game tests you need to get the game to send packets you want to see.</li><li>Stop the server. The script will print the filename of the trace file it generated. This usually looks something like <code>packets_123456789.txt</code>.</li></ol><p>This trace file will be used later on to generate further data, but it’s necessary to update BedrockProtocol before doing so.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Do not use <code>tracer.py</code> on a server with mods loaded. The BDS instance may crash or behave unexpectedly.</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>You may have difficulty joining a BDS server running inside WSL2 from a Windows Minecraft client. This is a long-standing issue between WSL2 and UWP apps and has no known fix. You can work around it by using a basic proxy script like <a href="https://github.com/pmmp/RakLib/blob/stable/tools/proxy.php" target="_blank" rel="noreferrer">RakLib proxy.php</a> and joining via the proxy instead of trying to connect directly. Alternatively, just run the server on a proper Linux machine or VM.</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you don’t want to use <code>tracer.py</code>, you can also create a packet trace using a proxy such as <a href="https://github.com/Sandertv/gophertunnel" target="_blank" rel="noreferrer">gophertunnel</a>. The structure of the file is simple: each line is starts with <code>read:</code> or <code>write:</code> followed by the packet buffer encoded as base64. However, a proxy may change the structure, order and timings of packets, so it may not give the same quality of data as the tracer script.</p></div><h2 id="step-2-update-code-in-bedrockprotocol-and-axolotl-pm" tabindex="-1">Step 2: Update code in BedrockProtocol and Axolotl-PM <a class="header-anchor" href="#step-2-update-code-in-bedrockprotocol-and-axolotl-pm" aria-label="Permalink to &quot;Step 2: Update code in BedrockProtocol and Axolotl-PM&quot;">​</a></h2><p><code>BedrockProtocol</code> is where most of the manual work needs to be done.</p><ol><li>Use <code>tools/update-from-bedrock-data.php</code> in <code>BedrockProtocol</code> to generate the basics from the data you generated for step 1. This will update a few enums and add stub classes for new packets. <strong>Files will not be removed for deleted packets.</strong></li><li>Analyze what changes need to be made to packet structures. This typically involves one or more of the following methods:</li></ol><blockquote><ul><li>Reading the official <a href="https://github.com/Mojang/bedrock-protocol-docs" target="_blank" rel="noreferrer">Minecraft Bedrock protocol documentation</a> - these are the easiest to use, but sometimes miss changes or are incorrect</li><li>Using tools like <a href="https://hex-rays.com/" target="_blank" rel="noreferrer">IDA</a> to decompile <code>bedrock_server_symbols.debug</code> and analyze packet source code (you need the x86_64 decompiler to work on BDS)</li></ul></blockquote><ol start="3"><li>Update packet structures and information in <code>BedrockProtocol</code>. This includes:</li></ol><blockquote><ul><li>Writing code to encode and decode new packets</li><li>Adjusting structures of existing packets and their subtypes if necessary</li><li>Updating constants and/or enums to match the new version</li><li>Whether new packet(s) should be clientbound, serverbound, or both</li></ul></blockquote><ol start="4"><li>Run <code>tools/generate-create-static-methods.php</code> in <code>BedrockProtocol</code>. This will update the <code>::create()</code> methods for all packets to match the new packet structures. (Make sure to run <code>php-cs-fixer</code> afterwards. It won’t break anything if you don’t, but the script will mess up the formatting.)</li><li>Do any necessary changes to Axolotl-PM to make it compatible with the updated <code>BedrockProtocol</code>. You can run PHPStan to find out where changes need to be made.</li></ol><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can link locally-modified versions of <code>BedrockProtocol</code> and related repositories to Axolotl-PM. This makes it easier to do integration testing without having to commit anything.</p><p>Use the provided <a href="https://github.com/axolotl-pm/PocketMine-MP/blob/stable/install-local-protocol.sh" target="_blank" rel="noreferrer">script</a> to link your local copies of <code>BedrockProtocol</code>, <code>BedrockBlockUpgradeSchema</code>, <code>BedrockItemUpgradeSchema</code>, and <code>BedrockData</code> to <code>Axolotl-PM</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you suspect that the official protocol documentation is incorrect, you can use tools like <a href="https://hex-rays.com/" target="_blank" rel="noreferrer">IDA</a> to decompile the BDS binary and analyze the packet code directly. However, this can be a very frustrating and time-consuming process, as <a href="https://hex-rays.com/" target="_blank" rel="noreferrer">IDA</a> is very slow and laggy when working with large binaries like BDS.</p><p>You can also use <code>gdb</code> to look at BDS’s compiled assembly code, which can be much faster, but is also much more difficult to understand.</p></div><h2 id="step-3-generating-supporting-data-part-2" tabindex="-1">Step 3: Generating supporting data (part 2) <a class="header-anchor" href="#step-3-generating-supporting-data-part-2" aria-label="Permalink to &quot;Step 3: Generating supporting data (part 2)&quot;">​</a></h2><h3 id="generating-the-remaining-files-for-bedrockdata" tabindex="-1">Generating the remaining files for BedrockData <a class="header-anchor" href="#generating-the-remaining-files-for-bedrockdata" aria-label="Permalink to &quot;Generating the remaining files for BedrockData&quot;">​</a></h3><p>Now that you’ve updated <code>BedrockProtocol</code>, use tools in <code>PocketMine-MP</code> to generate data from the packet trace you collected in part 1.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p><code>BedrockProtocol</code> code must be updated to handle the new version’s packets before trying to parse packet traces.</p></div><p>Use Axolotl-PM’s <code>tools/generate-bedrock-data-from-packets.php</code> to parse the packet trace <code>.txt</code> file you collected earlier, like so:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pocketmine-mp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/generate-bedrock-data-from-packets.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./packets_123456789.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../deps/BedrockData</span></span></code></pre></div><p>This will extract various information from the packet dump, like creative inventory items, crafting recipes, and more. Once you’ve done this, <code>BedrockData</code> is ready to publish. However, do not push anything to the master branch until the official Mojang release day.</p><h3 id="generating-a-blockstate-upgrade-schema" tabindex="-1">Generating a blockstate upgrade schema <a class="header-anchor" href="#generating-a-blockstate-upgrade-schema" aria-label="Permalink to &quot;Generating a blockstate upgrade schema&quot;">​</a></h3><p>Axolotl-PM uses JSON schemas to tell it how to upgrade blockstate NBT data in old world saves to the newest version.</p><p>Steps to generate a blockstate upgrade schema:</p><ol><li>Get the appropriate palette mapping file that the BDS mod generated. You can find it in <code>mapping_files/old_palette_mappings</code>, and the file name will be something like <code>1.20.80.24_beta_to_current_block_map.bin</code>.</li><li>Use Axolotl-PM’s <code>tools/blockstate-upgrade-schema-utils.php</code> to generate a new schema for this version.</li><li>Add the schema to the <code>nbt_upgrade_schema</code> folder of <code>BedrockBlockUpgradeSchema</code>. The name should be prefixed with a number to ensure the files are sorted correctly, like this: <code>0271_1.20.70.24_beta_to_1.20.80.24_beta.json</code>.</li><li>Commit the new schema. <strong>Do not commit directly to the master branch until the version is released.</strong></li></ol><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you can’t get a palette mapping file, you can write an upgrade schema by hand. However, this may be time-consuming and error-prone, and is not recommended unless you have no other choice.</p></div><h3 id="generating-an-item-upgrade-schema" tabindex="-1">Generating an item upgrade schema <a class="header-anchor" href="#generating-an-item-upgrade-schema" aria-label="Permalink to &quot;Generating an item upgrade schema&quot;">​</a></h3><p>Axolotl-PM uses JSON schemas to upgrade item data in old world saves to the newest version.</p><p>Steps to generate an item upgrade schema:</p><ol><li>Use Axolotl-PM’s <code>tools/generate-item-upgrade-schema.php</code>. Give it the path to <code>r16_to_current_item_map.json</code> in <code>BedrockData</code>, and the path to the already-existing schemas in <code>BedrockItemUpgradeSchema</code>.</li><li>Add the schema to the <code>id_meta_upgrade_schema</code> folder of <code>BedrockItemUpgradeSchema</code>. The name should be prefixed with a number to ensure the files are sorted correctly, like this: <code>0181_1.20.70.24_beta_to_1.20.80.24_beta.json</code>.</li><li>Commit the new schema. <strong>Do not commit directly to the master branch until the version is released.</strong></li></ol><h2 id="step-4-completing-changes-in-axolotl-pm-using-the-new-data" tabindex="-1">Step 4: Completing changes in Axolotl-PM using the new data <a class="header-anchor" href="#step-4-completing-changes-in-axolotl-pm-using-the-new-data" aria-label="Permalink to &quot;Step 4: Completing changes in Axolotl-PM using the new data&quot;">​</a></h2><p>Once you have finished generated supporting data, you may need to do a few more changes to Axolotl-PM.</p><p>This mostly involves updating the code in <code>src/data/bedrock/block</code> and <code>src/data/bedrock/item</code> to decode and encode data in the expected format for the newest version.</p><p>If you’re lucky, the version you’re updating to might not have changed anything at all. In this case, you won’t need to do anything.</p><p>Steps to do the changes:</p><ol><li>Run <code>composer update-codegen</code>.</li><li>Run <code>vendor/bin/phpstan</code>. This will tell you where you need to make changes.</li><li>Fix all the problems reported by PHPStan.</li><li>Make sure the following constants are updated correctly in <code>src/data/bedrock/WorldDataVersions.php</code>:</li></ol><table tabindex="0"><thead><tr><th>Constant</th><th>Frequency of change</th><th>Description</th></tr></thead><tbody><tr><td><code>LAST_OPENED_IN</code></td><td>Every update</td><td>Tells Minecraft what version what features the world uses</td></tr><tr><td><code>NETWORK</code></td><td>Every update</td><td>Prevents Minecraft from opening worlds which use features it doesn’t support</td></tr><tr><td><code>BLOCK_STATES</code></td><td>Often</td><td>Tells the world system whether block NBT needs upgrading</td></tr><tr><td><code>CHUNK</code></td><td>Rarely</td><td>Tells the world system what format saved chunks are in</td></tr><tr><td><code>SUBCHUNK</code></td><td>Rarely</td><td>Same again, but for subchunk data</td></tr><tr><td><code>STORAGE</code></td><td>Rarely</td><td>Tells the world system the general storage format to expect</td></tr></tbody></table><ol start="5"><li>Run <code>vendor/bin/phpunit tests/phpunit</code>. Make sure all the tests pass. If you’ve made a mistake somewhere, the tests should fail.</li></ol><h2 id="step-5-playtesting-axolotl-pm" tabindex="-1">Step 5: Playtesting Axolotl-PM <a class="header-anchor" href="#step-5-playtesting-axolotl-pm" aria-label="Permalink to &quot;Step 5: Playtesting Axolotl-PM&quot;">​</a></h2><p>Once you’ve made all the changes, you should playtest Axolotl-PM to make sure everything works as expected.</p><ol><li>Create a new world with Minecraft on the target version.</li><li>Load the world into Axolotl-PM and start the server.</li><li>Do whatever playtests you need to make sure your changes work as expected.</li></ol><h2 id="finally-committing-the-results" tabindex="-1">Finally: Committing the results <a class="header-anchor" href="#finally-committing-the-results" aria-label="Permalink to &quot;Finally: Committing the results&quot;">​</a></h2><p>Once you’re happy with your changes, commit the changes on all repositories. By convention, we recommend you name your branch like this: <code>bedrock-1.21.0</code>.</p><p>When the new version’s final release is out, merge the changes into the main branches and tag releases where appropriate.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>The <code>Bedrock*</code> repositories use tag metadata (suffixed using a <code>+</code> sign) to show which version of Minecraft they support. An example tag looks something like this: <code>1.9.0+bedrock-1.20.80</code>.</p><p>The metadata doesn’t affect dependency version resolution, but it can be useful for telling at a glance which version the repository supports.</p></div>`,72)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
